#include <stdio.h>

#define FILE_NAME "input.txt"
#define MAX_LEN 100

/* 判分环境下先把标准输入的全部内容写成 input.txt，充当题面里"命令行给出的那个文件" */
static void prepare_file(void)
{
    FILE *fp = fopen(FILE_NAME, "w");
    int ch;

    if (fp == NULL)
        return;
    while ((ch = getchar()) != EOF)
        fputc(ch, fp);
    fclose(fp);
}

/* 从 fp 中读入一行（最多 max 个字符，不含换行符），返回读入的字符个数 */
int get_line(char *str, int max, FILE *fp)
{
    int n = 0;
    int ch;

    while (n < max && (ch = fgetc(fp)) != EOF && ch != '\n') {
        str[n] = (char)ch;
        n = n + 1;
    }
    str[n] = '\0';

    return n;
}

int main(void)
{
    char str[MAX_LEN + 1];
    FILE *fp;
    int len;

    prepare_file();

    fp = fopen(FILE_NAME, "r");
    if (fp == NULL) {
        printf("str=\nlen=0\n");
        return 0;
    }
    len = get_line(str, MAX_LEN, fp);
    fclose(fp);

    printf("str=%s\n", str);
    printf("len=%d\n", len);

    return 0;
}

